$ErrorActionPreference='Stop'
$js=@'
let sockets=[];
try{
const targets=await(await fetch("http://127.0.0.1:17447/json/list")).json();
const ids=["EF6A592F8DA7E5C66A6F6046DBB9B113","99269AD269095748DC081498F3A72B77","1CCEF88CBF3B89E87F8DF6FA7EA20ECD"];
let out=[];
for(const id of ids){const t=targets.find(x=>x.id===id&&x.url.startsWith("https://www.avito.ru/krasnoyarsk/"));if(!t){out.push({id,error:"no_tab"});continue}
const s=new WebSocket(t.webSocketDebuggerUrl);sockets.push(s);
try{
const r=await Promise.race([new Promise((ok,no)=>{s.addEventListener("open",()=>s.send(JSON.stringify({id:220,method:"Runtime.evaluate",params:{expression:"window.scrollTo(0,1000);window.scrollY",returnByValue:true}})),{once:true});s.addEventListener("message",e=>{let x=JSON.parse(e.data);if(x.id===220)ok(x.result?.result?.value||0)});s.addEventListener("error",no,{once:true})}),new Promise((_,bad)=>setTimeout(()=>bad(Error("timeout")),4000))]);
out.push({id,scrollY:r})}catch(e){out.push({id,error:"timeout"})}s.close()}
console.log(JSON.stringify(out))
}catch(e){console.log(JSON.stringify({error:String(e).slice(0,120)}))}
for(let s of sockets)try{s.close()}catch{};process.exit(0)
'@
$tmp=Join-Path $env:TEMP 'pc-avito-scroll-comparison.mjs'
try{[System.IO.File]::WriteAllText($tmp,$js,[System.Text.UTF8Encoding]::new($false));& node.exe $tmp}finally{Remove-Item -LiteralPath $tmp -ErrorAction SilentlyContinue -Force}
